/// <summary>
///    The <c>METFTILinesUIBuilder</c> class is responsible for building an input dialog for the
///    <c>METFTILines</c> report.
/// </summary>
/// <remarks>
///    It adds custom lookups
/// </remarks>
public class METFTILinesUIBuilder extends SrsReportDataContractUIBuilder
{
}

Method.Source:
/// <summary>
/// Performs a dimension set lookup.
/// </summary>
/// <param name="_control">
/// The dimension set control.
/// </param>
/// <remarks>
/// This method uses the <c>DimensionAttribute</c> table for lookup.
/// </remarks>
public void lookupDimensionFocus(FormStringControl _control)
{
    DimensionHierarchyHelper::lookupDimensionSet(_control);
}

    /// <summary>
    /// Initialize the dialog fields after the fields have been built
    /// change the dimension focus dialog field to appear as lookup.
    /// </summary>
    public void postBuild()
    {
        DialogField         dimensionFocus;
        METFTILinesContract metFTILinesContract;

        super();

        metFTILinesContract = this.dataContractObject();

        // From binding info, get the dialog field for dimension attribute and add button
        dimensionFocus = this.bindInfo().getDialogField(metFTILinesContract, methodStr(metFTILinesContract, parmDimensionFocus));

        dimensionFocus.registerOverrideMethod(  methodstr(FormStringControl, lookup),
                                                methodstr(metFTILinesUIBuilder, lookupDimensionFocus),
                                                this);

    }

/// <summary>
/// Overrides the defaults in order to handle events on dialog boxes.
/// </summary>
public void postRun()
{
    super();
}
